namespace EProcure.Web.Services.External;

/// <summary>
/// Where uploaded files (application PDFs) are kept. The MVP stores them in a local folder
/// (LocalFileStorage); Azure Blob Storage or similar can replace it later without changing callers.
/// </summary>
public interface IFileStorage
{
    /// <summary>Saves the bytes and returns an opaque key generated by the server (never the user's file name).</summary>
    Task<string> SaveAsync(Stream content, string extension, CancellationToken ct);

    /// <summary>Opens a stored file for reading, or NULL if the key is unknown or invalid.</summary>
    Task<Stream?> OpenReadAsync(string key, CancellationToken ct);

    Task DeleteAsync(string key, CancellationToken ct);
}

/// <summary>Upload rules and storage location (appsettings.json "Uploads").</summary>
public class UploadOptions
{
    /// <summary>5 MB by default.</summary>
    public long MaxFileSizeBytes { get; set; } = 5 * 1024 * 1024;

    /// <summary>Relative to the app's content root, and deliberately NOT under wwwroot (not reachable by URL).</summary>
    public string LocalRoot { get; set; } = "App_Data/uploads";
}
